(function(root){
    function div(a,b){return ~~(a/b);}
    function mod(a,b){return a-Math.floor(a/b)*b;}
    function toJalali(gy,gm,gd){
        var g_d_m=[0,31,59,90,120,151,181,212,243,273,304,334],
            jy=(gy>1600)?979:0;
        gy-= (gy>1600)?1600:621;
        var gy2=(gm>2)?gy+1:gy;
        var days=365*gy+div(gy2+3,4)-div(gy2+99,100)+div(gy2+399,400)-80+gd+g_d_m[gm-1];
        jy+=33*div(days,12053);
        days%=12053;
        jy+=4*div(days,1461);
        days%=1461;
        if(days>365){
            jy+=div(days-1,365);
            days=(days-1)%365;
        }
        var jm=(days<186)?1+div(days,31):7+div(days-186,30);
        var jd=1+((days<186)?mod(days,31):mod(days-186,30));
        return {year:jy,month:jm,day:jd};
    }
    function toGregorian(jy,jm,jd){
        jy=(jy>979)?jy-979:jy;
        var days=365*jy+div(jy,33)*8+div(mod(jy,33)+3,4);
        days+=(jm<7)?(jm-1)*31:(jm-7)*30+186;
        days+=jd-1;
        var g=days+79;
        var gy=1600+400*div(g,146097);
        g=mod(g,146097);
        if(g>=36525){
            gy+=100*div(--g,36524);
            g=mod(g,36524);
            if(g>=365){
                gy+=4*div(g,1461);
                g=mod(g,1461);
                if(g>=366){
                    gy+=div(g-1,365);
                    g=mod(g-1,365);
                }
            }
        }
        var gd=g+1,
            sal_kab=(gy%4==0 && gy%100!=0)||gy%400==0,
            kab=[0,31,(sal_kab?29:28),31,30,31,30,31,31,30,31,30,31];
        var gm=0;
        for(gm=1;gm<=12&&gd>kab[gm];gm++) gd-=kab[gm];
        return {year:gy,month:gm,day:gd};
    }
    function format(num){return num<10?"0"+num:num;}
    function PersianDate(input){
        if(!(this instanceof PersianDate))return new PersianDate(input);
        var g;
        if(!input) g=new Date();
        else if(input instanceof Date) g=input;
        else if(typeof input==="number") g=new Date(input);
        else throw "Invalid PersianDate input";
        var j=toJalali(g.getFullYear(),g.getMonth()+1,g.getDate());
        this.y=j.year;
        this.m=j.month;
        this.d=j.day;
        this.g=g;
    }
    PersianDate.prototype.format=function(f){
        return f.replace(/YYYY/g,this.y)
            .replace(/MM/g,format(this.m))
            .replace(/DD/g,format(this.d));
    };
    PersianDate.prototype.toDate=function(){
        var g=toGregorian(this.y,this.m,this.d);
        return new Date(g.year,g.month-1,g.day,this.g.getHours(),this.g.getMinutes(),this.g.getSeconds(),this.g.getMilliseconds());
    };
    PersianDate.prototype.unix=function(){return Math.floor(this.toDate().getTime()/1000);};
    root.persianDate=PersianDate;
})(this);
